import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.ChTAMbUy.js";const k=JSON.parse('{"title":"Knative Services","description":"","frontmatter":{},"headers":[],"relativePath":"1.9/mlops/knative.md","filePath":"versions/1.9/mlops/knative.md","lastUpdated":1791569256000}'),n={name:"1.9/mlops/knative.md"};function r(l,e,o,h,p,c){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="knative-services" tabindex="-1">Knative Services <a class="header-anchor" href="#knative-services" aria-label="Permalink to &quot;Knative Services&quot;">​</a></h1><p>prokube exposes Knative Serving for running auto-scaling containerised HTTP services in your workspace.</p><div class="info custom-block"><p class="custom-block-title">Knative documentation</p><p>Upstream references:</p><ul><li><a href="https://knative.dev/docs/serving/" target="_blank" rel="noreferrer">Knative Serving documentation</a></li><li><a href="https://knative.dev/docs/serving/services/" target="_blank" rel="noreferrer">Knative Service YAML reference</a></li><li><a href="https://knative.dev/docs/serving/autoscaling/" target="_blank" rel="noreferrer">Knative autoscaling</a></li></ul></div><h2 id="when-to-use-knative-directly" tabindex="-1">When to Use Knative Directly <a class="header-anchor" href="#when-to-use-knative-directly" aria-label="Permalink to &quot;When to Use Knative Directly&quot;">​</a></h2><p>Knative Serving runs any HTTP container with automatic scaling, including scale-to-zero. Use it to host classic microservices – REST APIs, web apps, background workers, or any HTTP workload that does not fit a higher-level abstraction.</p><p>The platform provides dedicated solutions for common workload types. Prefer those over a plain Knative service:</p><table tabindex="0"><thead><tr><th>Workload</th><th>Use instead</th></tr></thead><tbody><tr><td>ML model inference</td><td><a href="./model_serving.html">KServe InferenceServices</a> – model runtimes, storage, inference protocols, automatic <code>/svc/serving/...</code> URL</td></tr><tr><td>LLM serving (vLLM, HuggingFace)</td><td><a href="./../agentops/">AgentOps documentation</a> – OpenAI-compatible endpoints, GPU scaling, dedicated runtimes</td></tr><tr><td>MCP servers</td><td><a href="./../agentops/mcp_servers.html">MCP Servers</a> – tool-provisioning protocol with lifecycle management</td></tr></tbody></table><p>KServe InferenceServices and Knative services share the same external path family, <code>/svc/serving/&lt;workspace&gt;/&lt;name&gt;</code>. A Knative service therefore cannot use the same name as an InferenceService in the same workspace.</p><table tabindex="0"><thead><tr><th>Aspect</th><th>KServe InferenceService</th><th>Knative Service</th></tr></thead><tbody><tr><td>Use case</td><td>ML model inference</td><td>Any HTTP container</td></tr><tr><td>External URL</td><td>Automatic <code>/svc/serving/...</code></td><td>Automatic <code>/svc/serving/...</code></td></tr><tr><td>Model storage</td><td>Built-in (S3, MLflow, HTTP)</td><td>Manual</td></tr><tr><td>Inference protocol</td><td>V1 / V2 built-in</td><td>Custom</td></tr><tr><td>UI page</td><td>Models</td><td>Knative Services</td></tr></tbody></table><h2 id="get-started" tabindex="-1">Get Started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get Started&quot;">​</a></h2><p>Deploy the official Knative hello world sample – no container image to build.</p><h3 id="_1-create-the-service" tabindex="-1">1) Create the Service <a class="header-anchor" href="#_1-create-the-service" aria-label="Permalink to &quot;1) Create the Service&quot;">​</a></h3><p>The example uses <code>gcr.io/knative-samples/helloworld-go</code> – a public image that responds with <code>Hello World!</code> on any request. Paste this manifest into the <strong>YAML</strong> tab of the <strong>Deploy Service</strong> wizard and click <strong>Deploy from YAML</strong>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">apiVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">serving.knative.dev/v1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">kind</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Service</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">metadata</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hello</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    spec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      containers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">gcr.io/knative-samples/helloworld-go</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          ports</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">containerPort</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8080</span></span></code></pre></div><p>Or save it as <code>hello.yaml</code> and apply it from a Lab terminal:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.yaml</span></span></code></pre></div><h3 id="_2-test-the-service" tabindex="-1">2) Test the Service <a class="header-anchor" href="#_2-test-the-service" aria-label="Permalink to &quot;2) Test the Service&quot;">​</a></h3><p>After submitting, a new entry appears in the Knative Services list. Once its status shows <strong>Ready</strong>, the service is reachable from inside the cluster. In a Lab terminal, run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://hello.</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">namespac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.svc.cluster.local</span></span></code></pre></div><p>Expected response: <code>Hello World!</code></p><p>The Knative Services list shows the <code>hello</code> service with a <strong>Ready</strong> status. Open its detail page to inspect the service further.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/mlops/knative/hello-serivce-in-list.png" alt="Knative Services list with hello service Ready" loading="lazy"></p><p>The <strong>Logs</strong> tab streams pod logs for the service instance.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/mlops/knative/knative-logs.png" alt="Knative Service logs tab" loading="lazy"></p><p>The <strong>Conditions</strong> tab shows the Knative service readiness conditions.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/mlops/knative/knative-conditions.png" alt="Knative Service conditions tab" loading="lazy"></p><p>For your own services, build a container image that listens on the port declared by Knative&#39;s <code>PORT</code> environment variable (default <code>8080</code>). You can <a href="./../labs/#building-container-images">build and push images from a Lab</a> – the prokube-maintained notebook images include Docker CLI and Buildx with a remote BuildKit service.</p><p>Knative can run any HTTP container. Upstream Knative provides <a href="https://knative.dev/docs/samples/" target="_blank" rel="noreferrer">samples for common languages and frameworks</a>; one of the most straightforward patterns is a <a href="https://knative.dev/docs/samples/serving/hello-world/helloworld-python/" target="_blank" rel="noreferrer">FastAPI service</a> – define a few routes, build a container, and deploy it as a Knative service.</p><h2 id="call-the-service-from-outside-the-cluster" tabindex="-1">Call the Service from Outside the Cluster <a class="header-anchor" href="#call-the-service-from-outside-the-cluster" aria-label="Permalink to &quot;Call the Service from Outside the Cluster&quot;">​</a></h2><p><a href="./../platform/agent_gateway.html">Agent Gateway</a> exposes every Knative service in the workspace automatically, with no extra routing resources:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;your-prokube-domain&gt;/svc/serving/&lt;workspace&gt;/&lt;service-name&gt;</span></span></code></pre></div><p>External requests need an <a href="./../platform/api_keys.html">API key</a> scoped to the service. On the <strong>API Keys</strong> page, create a key and select the Knative service under <strong>Select Services</strong>. Then call the <code>hello</code> service from the example:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://&lt;your-prokube-domain&gt;/svc/serving/&lt;workspace&gt;/hello&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer &lt;api-key&gt;&quot;</span></span></code></pre></div><p>If the key was created with the <code>x-api-key</code> format, send <code>-H &quot;x-api-key: &lt;api-key&gt;&quot;</code> instead.</p><h2 id="access-notes" tabindex="-1">Access Notes <a class="header-anchor" href="#access-notes" aria-label="Permalink to &quot;Access Notes&quot;">​</a></h2><p>Inside the cluster, call the Knative service directly through its internal URL (<code>&lt;service-name&gt;.&lt;namespace&gt;.svc.cluster.local</code>). From outside, requests to <code>/svc/serving/*</code> go through <a href="./../platform/agent_gateway.html">Agent Gateway</a> and require an API key. See <a href="./../platform/api_keys.html">API Keys</a> for details.</p><p>From a Lab terminal, test the <code>hello</code> service with:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://hello.</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">namespac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.svc.cluster.local</span></span></code></pre></div><h2 id="scaling" tabindex="-1">Scaling <a class="header-anchor" href="#scaling" aria-label="Permalink to &quot;Scaling&quot;">​</a></h2><p>Knative scales automatically based on HTTP request concurrency. The defaults work for most services. To prevent scale-to-zero, set the minimum number of instances:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    metadata</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      annotations</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        autoscaling.knative.dev/min-scale</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1&quot;</span></span></code></pre></div><p>See the upstream <a href="https://knative.dev/docs/serving/autoscaling/" target="_blank" rel="noreferrer">Knative autoscaling documentation</a> for detailed options.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>Check the service status from the <strong>Conditions</strong> tab in the UI or via kubectl:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> describe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ksvc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello</span></span></code></pre></div><p>Common causes:</p><ul><li><strong>Image pull errors</strong> – verify the image reference and registry credentials.</li><li><strong>Container crash loop</strong> – check pod logs from the <strong>Logs</strong> tab.</li><li><strong>Not becoming ready</strong> – the container must listen on the port declared by <code>PORT</code>. Verify the application binds to <code>0.0.0.0</code> and the correct port.</li><li><strong>External URL returns 404</strong> – verify the workspace and service name in the <code>/svc/serving/&lt;workspace&gt;/&lt;service-name&gt;</code> path, and that the service is <strong>Ready</strong>.</li><li><strong>External URL returns 401</strong> – missing or invalid API key. See <a href="./../platform/api_keys.html">API Keys</a>.</li></ul><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./model_serving.html">Model Serving</a></li><li><a href="./../platform/api_keys.html">API Keys</a></li><li><a href="./../labs/">Labs</a></li></ul>`,49)])])}const g=s(n,[["render",r]]);export{k as __pageData,g as default};
